UPDATE sale_off SET
	result		= #{CJSResultCode}
	,result_msg = #{CJSResultMessage}
	,pay_id		= #{CJSPayID}
	,trade_id	= #{CJSTradeID}
	,pay_date	= #{CJSPaydate}
	,pgctrl		= #{Crd_pgctrl_Cd_p}
WHERE
	sale_id 			= #{saleId}

UPDATE sale_off SET
	cancel=#{cancel}
	,cancel_memo=#{cancelMemo}
	,cancel_cd=#{cancelCd}
	,cancel_date = DATE_FORMAT(now(),'%Y.%m.%d')
WHERE
	sale_id 			= #{saleId}

UPDATE sale_off SET
	hist_id		= #{histId}
WHERE
	sale_id 			= #{saleId}

UPDATE sale_off SET
	result				= #{result}
WHERE
	sale_id 			= #{saleId}

	UPDATE sale_off SET
    	result				= #{result}
    	,ogn_price			= ogn_price+#{ognPrice}
    WHERE
    	sale_id 			= #{saleId}

	UPDATE sale_off SET
    	result				= #{result}
    	,pay_card			= pay_card + #{payCard}
    	,pay_cash			= pay_cash + #{payCash}
    	,card_ty			= #{cardTy}
    	,card_date			= #{cardDate}
    	,pay_point			= pay_point + #{payPoint}
    	,partner_dscnt		= #{partnerDscnt}
    	,partner_id			= #{partnerId}
    	,dscnt_price		= #{dscntPrice}
    	,etc_dscnt			= #{etcDscnt}
    	,etc_dscnt_memo		= #{etcDscntMemo}
    	,earn_prcnt			= #{earnPrcnt}
    WHERE
    	sale_id 			= #{saleId}

